"""Standalone HTML report for Schema Watch results."""
from html import escape

def render_report(result):
    changes=result['breaking_changes'];warnings=result['coverage_warnings']
    def cards(items,kind):
        output=[]
        for item in items:
            title=item.get('operation') or item.get('path') or item.get('kind','Coverage warning')
            detail=', '.join(f'{key}: {value}' for key,value in item.items() if key not in {'operation','path'})
            output.append(f'<li data-kind="{kind}"><b>{escape(str(title))}</b><span>{escape(detail)}</span></li>')
        return ''.join(output)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Schema Watch report</title><style>{STYLE}</style></head><body><a class="skip" href="#results">Skip to results</a><header><strong>SCHEMA / WATCH</strong><span>LOCAL COMPATIBILITY REPORT</span></header><main><p class="eyebrow">OPENAPI CHANGE INTELLIGENCE</p><h1>Know what breaks<br><em>before it ships.</em></h1><section class="summary"><article><b>{len(changes)}</b><span>BREAKING CHANGES</span></article><article><b>{len(warnings)}</b><span>COVERAGE WARNINGS</span></article><p>{escape(result['scope'])}</p></section><nav aria-label="Result filters"><button class="active" data-filter="all">All findings</button><button data-filter="breaking">Breaking only</button><button data-filter="warning">Warnings only</button></nav><section id="results"><ol>{cards(changes,'breaking')}{cards(warnings,'warning')}</ol><p id="empty" hidden>No findings in this view.</p></section><p class="note">No findings is not proof of compatibility. Review coverage warnings and the documented supported scope.</p></main><script>{SCRIPT}</script></body></html>'''

STYLE='''*{box-sizing:border-box}:root{color-scheme:dark;--bg:#0a0c10;--panel:#13171e;--line:#303846;--ink:#f6f2e9;--muted:#9aa4b3;--lime:#b7f36b;--red:#ff735d;--amber:#ffc761}body{margin:0;background:linear-gradient(120deg,#101a18 0,transparent 42%),var(--bg);color:var(--ink);font:15px/1.55 system-ui,sans-serif}header,main{max-width:1200px;margin:auto}header{display:flex;justify-content:space-between;padding:25px 5vw;border-bottom:1px solid var(--line);font:11px ui-monospace,monospace;letter-spacing:2px}header strong{color:var(--lime)}main{padding:60px 5vw 80px}.eyebrow{color:var(--lime);font:10px ui-monospace,monospace;letter-spacing:3px}h1{font-size:clamp(45px,8vw,92px);line-height:.96;letter-spacing:-.065em;margin:18px 0 44px}h1 em{color:var(--lime);font-style:normal}.summary{display:grid;grid-template-columns:210px 210px 1fr;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--panel)}.summary article,.summary p{padding:20px;margin:0;border-right:1px solid var(--line)}.summary b{display:block;font:40px ui-monospace,monospace}.summary span{color:var(--muted);font:10px ui-monospace,monospace;letter-spacing:1px}.summary p{color:var(--muted);border:0}nav{display:flex;gap:10px;margin:34px 0 14px}button{border:1px solid var(--line);border-radius:99px;background:transparent;color:var(--ink);padding:9px 14px;cursor:pointer}button.active{background:var(--lime);border-color:var(--lime);color:#17210a}button:focus-visible{outline:3px solid var(--lime);outline-offset:3px}ol{list-style:none;margin:0;padding:0;border:1px solid var(--line);border-radius:14px;overflow:hidden}li{display:grid;grid-template-columns:minmax(180px,.6fr) 1fr;gap:20px;padding:18px 20px;background:var(--panel);border-bottom:1px solid var(--line)}li:last-child{border:0}li b{color:var(--red)}li[data-kind=warning] b{color:var(--amber)}li span,.note,#empty{color:var(--muted);overflow-wrap:anywhere}.skip{position:absolute;top:-100px;left:10px;background:var(--lime);color:#000;padding:8px}.skip:focus{top:10px}@media(max-width:700px){.summary{grid-template-columns:1fr 1fr}.summary p{grid-column:1/-1;border-top:1px solid var(--line)}li{grid-template-columns:1fr}h1{font-size:48px}header span{display:none}}'''
SCRIPT='''const buttons=document.querySelectorAll('[data-filter]'),rows=[...document.querySelectorAll('#results li')],empty=document.querySelector('#empty');for(const button of buttons)button.onclick=()=>{for(const item of buttons)item.classList.toggle('active',item===button);let visible=0;for(const row of rows){const show=button.dataset.filter==='all'||row.dataset.kind===button.dataset.filter;row.hidden=!show;visible+=show}empty.hidden=visible>0};'''
